-- CI-043 v2.2 rev b MANDATORY PRE-CHECK (unchanged logic; operational health findings are not evaluated here). Run IMMEDIATELY before apply; apply ONLY if every row passes. A failing count/max row from legitimate activity means STOP, investigate and re-baseline with the owner - never automatic recovery (read-only). Baseline literals: production 27 Oct 2026 18:10 IST (after CI-042 v2.2).
with chk(check_name, expected, actual) as (
  select 'H01 combined fingerprint 119/122/143', '3e5515ed97189b747ea3a8d18c3f4411', (select md5(string_agg(md5(costing.fn_compute_run_fingerprint(r)::text),'|' order by r)) from unnest(array[119,122,143]) r)
  union all select 'H02 queued/running runs', '0', (select count(*)::text from costing.costing_refresh_run where overall_status in ('QUEUED','RUNNING'))
  union all select 'H03 runs count/max', '118/143', (select count(*)||'/'||max(id) from costing.costing_refresh_run)
  union all select 'H04 audit rows count/max id', '17/21', (select count(*)||'/'||max(audit_id) from costing.cost_period_governance_audit)
  union all select 'H05 designation rows count/max id', '9/11', (select count(*)||'/'||max(id) from costing.costing_run_designation)
  union all select 'H06 fingerprint rows count/max id', '28/30', (select count(*)||'/'||max(id) from costing.costing_run_fingerprint)
  union all select 'H07 effective designations', '119=REFERENCE,122=APPROVED,128=REVOKED,136=REVOKED,140=REVOKED,143=APPROVED', (select string_agg(refresh_run_id||'='||designation, ',' order by refresh_run_id) from costing.v_costing_run_effective_designation)
  union all select 'H08 periods', '2026-03-01:OPEN:2026-03-31 2026-06-01:OPEN:2026-06-30 2026-07-01:OPEN:2026-07-22 2026-08-01:OPEN:2026-08-07 2026-09-01:LOCKED:2026-09-10 2026-10-01:OPEN:2026-10-22', (select string_agg(period_start||':'||status||':'||valuation_date, ' ' order by period_start) from costing.cost_periods)
  union all select 'H17 cron 66/67/68 active + command md5', '66:true:0045bba6068cf31ac53852d6b743a745 67:true:0045bba6068cf31ac53852d6b743a745 68:true:c3b74bfc510dd2b4dc061217ff43eef6', (select string_agg(jobid||':'||active||':'||md5(command), ' ' order by jobid) from cron.job where jobid in (66,67,68))
  union all select 'H20 CI-043 objects absent', '', concat_ws(',', to_regprocedure('costing.fn_costing_health_check(date)'), to_regprocedure('public.rpc_costing_health_check()'))
  union all select 'H21 settings rows (only CI-040/041)', 'approval_preview_ack_ttl_minutes=15,scheduler_catch_up_max_runs=1,scheduler_max_retries=2', (select string_agg(setting_key||'='||int_value, ',' order by setting_key collate "C") from costing.costing_automation_setting)
  union all select 'H22 settings range constraint already admits the 9 health_* keys', 'true', (select (pg_get_constraintdef(oid) like '%health_quarter_lock_warn_days%' and pg_get_constraintdef(oid) like '%health_retry_overdue_minutes%')::text from pg_constraint where conrelid='costing.costing_automation_setting'::regclass and conname='costing_automation_setting_range_chk')
  union all select 'H23 dependency md5 fn_costing_failure_class / v_costing_run_effective_designation', '99dfd6127856d48b3bb9e0979053db65,b324068d66aef0c14bc6d47a921c6d56', md5(pg_get_functiondef('costing.fn_costing_failure_class(text)'::regprocedure))||','||md5(pg_get_viewdef('costing.v_costing_run_effective_designation'::regclass))
  union all select 'H25 no health_* key exists with a value different from the CI-043 default', '', (select coalesce(string_agg(s.setting_key||'='||s.int_value, ',' order by s.setting_key collate "C"),'') from costing.costing_automation_setting s join (values ('health_quarter_lock_warn_days',45),('health_quarter_lock_info_days',30),('health_draft_freshness_days',8),('health_draft_review_days',14),('health_queued_stuck_hours',2),('health_running_stuck_hours',6),('health_preview_ack_unused_warn_count',50),('health_preview_ack_unused_min_age_days',30),('health_retry_overdue_minutes',20)) d(k,v) on d.k=s.setting_key where s.int_value<>d.v)
  union all select 'H24 cron job count / max id', '34/68', (select count(*)||'/'||max(jobid) from cron.job)
)
select check_name, expected, actual, coalesce(expected = actual, false) pass from chk
union all select 'ALL PRE-CHECKS PASS', 'true', (select bool_and(coalesce(expected=actual,false))::text from chk), (select bool_and(coalesce(expected=actual,false)) from chk);
